<?php
declare(strict_types=1);require_once __DIR__.'/includes/functions.php';require_login();$uid=(int)current_user()['id'];
if(isset($_GET['open'])){$nid=(int)$_GET['open'];$stmt=db()->prepare('SELECT link_url FROM notifications WHERE id=? AND user_id=?');$stmt->execute([$nid,$uid]);$link=$stmt->fetchColumn();db()->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE id=? AND user_id=?')->execute([$nid,$uid]);if($link){header('Location: '.$link);exit;}redirect('notifications.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('UPDATE notifications SET is_read=1,read_at=COALESCE(read_at,NOW()) WHERE user_id=?')->execute([$uid]);flash('success','All notifications marked as read.');redirect('notifications.php');}
$stmt=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$stmt->execute([$uid]);$items=$stmt->fetchAll();$pageTitle='Notifications';require __DIR__.'/includes/header.php';?>
<section class="section container narrow-wide"><div class="section-heading"><div><span class="eyebrow">Updates</span><h1>Notifications</h1></div><form method="post"><?=csrf_field()?><button class="button button-ghost">Mark all as read</button></form></div><div class="notification-list"><?php if(!$items):?><div class="empty-state"><h3>You’re all caught up</h3><p>Comments, follows and moderation updates will appear here.</p></div><?php endif;?><?php foreach($items as $n):?><a class="notification <?=$n['is_read']?'':'unread'?>" href="<?=e(url('notifications.php?open='.$n['id']))?>"><span class="notification-icon"><?=match($n['type']){'comment'=>'💬','follow'=>'◎','moderation'=>'✓',default=>'•'}?></span><span><strong><?=e(ucfirst($n['type']))?></strong><p><?=e($n['message'])?></p><small><?=e(date('j M Y, g:i a',strtotime($n['created_at'])))?></small></span></a><?php endforeach;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
